public String separateNumbers(String s) {
    int n = s.length();
    if (s.charAt(0) == '0') return "NO";
    for (int len = 1; len <= n / 2; len++) {
        long first = Long.parseLong(s.substring(0, len));
        StringBuilder built = new StringBuilder(s.substring(0, len));
        long x = first;
        while (built.length() < n) {
            x++;
            built.append(x);
        }
        if (built.toString().equals(s)) {
            return "YES " + first;
        }
    }
    return "NO";
}

