public String separateNumbers(String s) {
    int n = s.length();
    if (s.charAt(0) == '0') return "NO";
    for (int len = 1; len <= n / 2; len++) {
        long x = Long.parseLong(s.substring(0, len));
        int idx = len;
        long next = x;
        boolean ok = true;
        while (idx < n) {
            next++;
            String ns = Long.toString(next);
            if (idx + ns.length() > n || !s.startsWith(ns, idx)) { ok = false; break; }
            idx += ns.length();
        }
        if (ok && idx == n) return "YES " + x;
    }
    return "NO";
}

