def separate_numbers(self, s: str) -> str:
    n = len(s)
    if s[0] == '0':
        return "NO"
    for length in range(1, n // 2 + 1):
        x = int(s[:length])
        idx = length
        nxt = x
        ok = True
        while idx < n:
            nxt += 1
            ns = str(nxt)
            if not s.startswith(ns, idx):
                ok = False
                break
            idx += len(ns)
        if ok and idx == n:
            return f"YES {x}"
    return "NO"

